                rects.append((bc,(r0,r1,c0,c1)))
            else:
                strays.extend(comp)
        else:
            strays.extend(comp)
    res=[[0]*W for _ in range(H)]
    for bc,(r0,r1,c0,c1) in rects:
        inner=[(i,j) for i in range(r0+1,r1) for j in range(c0+1,c1)]
        near=min(strays,key=lambda p: abs(p[0]- (r0+r1)/2)+abs(p[1]- (c0+c1)/2))
        sc=I[near[0]][near[1]]
        par=((near[0]%2)^ (near[1]%2))
        for i in range(r0+1,r1):
            for j in range(c0+1,c1):
                if ((i-r0)%2==0)==(par):
                    res[i][j]=sc
    for p in strays: res[p[0]][p[1]]=0
