    for dx in (-1,0,1):
        T_ = (np.isfinite(T[dy:dy+2,dx:dx+2]) if False else T[dy:,dx:]) if False else None
# proper flood fill: BFS from edge over 0-cells
from collections import deque
lab=np.zeros_like(T,int); q=deque()
for r in range(T.shape[0]):
    for c in [0,T.shape[1]-1]:
        if T[r,c]==0 and lab[r,c]==0: q.append((r,c)); lab[r,c]=1
