    for r in [0,T.shape[0]-1]:
        if T[r,c]==0 and lab[r,c]==0: q.append((r,c)); lab[r,c]=1
while q:
    r,c=q.popleft()
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        nr,nc=r+dr,c+dc
        if 0<=nr<T.shape[0] and 0<=nc<T.shape[1] and T[nr,nc]==0 and lab[nr,nc]==0:
            q.append((nr,nc)); lab[nr,nc]=1
enc=lab==0   # enclosed holes
