T=np.array(load()); H,W=T.shape
out=T.copy()
# every connected zero region fully surrounded (not touching image edge) takes
# the majority color among its border-adjacent nonzero cells; single-cell objects
# take surroundings; leftover stray noise outside anything becomes background
seen=np.zeros_like(T,bool)
for r in range(H):
    for c in range(W):
        if T[r,c]==0 and not seen[r,c]:
            d=[(r,c)]; seen[r,c]=True; comp=[]; surround=Counter(); touchEdge=False
            while d:
                rr,cc=d.pop(); comp.append((rr,cc))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=rr+dr,cc+dc
                    if 0<=nr<H and 0<=nc<W:
                        if not seen[nr,nc] and T[nr,nc]==0:
