    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

g=G['Test input']; H,W=len(g),len(g[0])
# collect candidate components of same color (4-connectivity), size >=3 -> keep border if closed
def comps(grid):
    seen=[[False]*len(r) for r in grid]; out=[]
    for i in range(H):
        for j in range(W):
            if seen[i][j] or grid[i][j]==0: continue
            st=[(i,j)]; c=grid[i][j]; seen[i][j]=True; cells=[]
            while st:
                a,b=st.pop(); cells.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and not seen[x][y] and grid[x][y]==c:
                        seen[x][y]=True; st.append((x,y))
            out.append((c,cells))
    return out
CC=comps(g)
res=[r[:] for r in g]
for c,cells in CC:
    if len(cells)<3:
        for a,b in cells: res[a][b]=0
print(json.dumps(res))

